// رندررهای بلاک‌های موضوعی (Phase 5.11، G8): poetry، prose-commentary، timeline، map، portrait، argument، proof.
// قرارداد: متن ساده escape می‌شود؛ فیلدهای html خام می‌مانند (همان قرارداد بلاک‌های قبلی).
// هر فیلد اختیاری است و ورودی تهی نباید خطا بدهد.
import { escHtml } from "../escape.js";
import { textHTML } from "./shared.js";
import type { AnnotatedLine, BlockMap, Renderer, TextFields } from "../types.js";

// متن یک آیتم: رشته (escape می‌شود) یا شیء با html/text/definition.
function itemHTML(item: unknown): string {
  if (item == null) return "";
  if (typeof item === "string") return escHtml(item);
  if (typeof item === "object") return textHTML(item as TextFields);
  return escHtml(String(item));
}

function asArray<T>(value: (T | null | undefined)[] | null | undefined): NonNullable<T>[] {
  return Array.isArray(value) ? (value.filter((v) => v != null) as NonNullable<T>[]) : [];
}

export const renderPoetry: Renderer<BlockMap["poetry"]> = (b) => {
  const title = b.title ? `<div class="rd-poetry-title">${escHtml(b.title)}</div>` : "";
  let stanzas = "";
  let current = "";
  const flush = () => {
    if (current) stanzas += `<div class="rd-poetry-stanza">${current}</div>`;
    current = "";
  };
  for (const raw of asArray<AnnotatedLine | string>(b.lines)) {
    // خط خالی یعنی شروع بند جدید
    const isObj = typeof raw === "object";
    const text = isObj ? (raw as AnnotatedLine).text : (raw as string);
    if (text == null || String(text).trim() === "") {
      flush();
      continue;
    }
    const rhyme =
      isObj && (raw as AnnotatedLine).rhyme
        ? `<span class="rd-poetry-rhyme" aria-hidden="true">${escHtml(String((raw as AnnotatedLine).rhyme))}</span>`
        : "";
    current += `<p class="rd-poetry-line">${rhyme}${escHtml(String(text))}</p>`;
  }
  flush();
  return `<figure class="rd-poetry">${title}${stanzas}</figure>`;
};

export const renderProseCommentary: Renderer<BlockMap["prose-commentary"]> = (b) => {
  const notes = asArray(b.notes)
    .map((n) => `<li class="rd-prose-note">${itemHTML(n)}</li>`)
    .join("");
  const aside = notes ? `<aside class="rd-prose-notes"><ol>${notes}</ol></aside>` : "";
  return `<div class="rd-prose-commentary"><div class="rd-prose-body">${textHTML(b)}</div>${aside}</div>`;
};

export const renderTimeline: Renderer<BlockMap["timeline"]> = (b) => {
  const title = b.title ? `<div class="rd-timeline-title">${escHtml(b.title)}</div>` : "";
  const events = asArray(b.events)
    .map(
      (ev) =>
        `<li class="rd-timeline-event">` +
        (ev.date ? `<time class="rd-timeline-date">${escHtml(String(ev.date))}</time>` : "") +
        (ev.title ? `<b class="rd-timeline-t">${escHtml(ev.title)}</b>` : "") +
        (ev.html != null || ev.text != null || ev.definition != null
          ? `<div class="rd-timeline-body">${textHTML(ev)}</div>`
          : "") +
        `</li>`,
    )
    .join("");
  return `<div class="rd-timeline">${title}<ol class="rd-timeline-list">${events}</ol></div>`;
};

// پین‌ها با مختصات درصدی (۰ تا ۱۰۰) روی تصویر پس‌زمینه قرار می‌گیرند.
function pct(v: unknown): number {
  const n = typeof v === "number" ? v : Number(v);
  if (!Number.isFinite(n)) return 0;
  return Math.min(100, Math.max(0, n));
}

export const renderMap: Renderer<BlockMap["map"]> = (b) => {
  const title = b.title ? `<div class="rd-map-title">${escHtml(b.title)}</div>` : "";
  const bg = b.src ? ` style="background-image:url('${escHtml(String(b.src))}')"` : "";
  const pins = asArray(b.pins)
    .map(
      (p) =>
        `<span class="rd-map-pin" style="inset-inline-start:${pct(p.x)}%;top:${pct(p.y)}%" title="${escHtml(String(p.label || ""))}">` +
        `<span class="rd-map-pin-label">${escHtml(String(p.label || ""))}</span></span>`,
    )
    .join("");
  const list = asArray(b.pins)
    .map((p) => `<li>${escHtml(String(p.label || ""))}</li>`)
    .join("");
  return (
    `<figure class="rd-map">${title}` +
    `<div class="rd-map-stage"${bg}>${pins}</div>` +
    (list ? `<ul class="rd-map-legend">${list}</ul>` : "") +
    `</figure>`
  );
};

export const renderPortrait: Renderer<BlockMap["portrait"]> = (b) => {
  const img = b.image
    ? `<img class="rd-portrait-img" src="${escHtml(String(b.image))}" alt="${escHtml(String(b.name || ""))}" loading="lazy" />`
    : "";
  const dates = [b.born, b.died]
    .filter((d) => d != null && d !== "")
    .map((d) => escHtml(String(d)));
  const meta =
    (b.role ? `<div class="rd-portrait-role">${escHtml(b.role)}</div>` : "") +
    (dates.length ? `<div class="rd-portrait-dates">${dates.join(" – ")}</div>` : "");
  const traits = asArray(b.traits)
    .map((t) => `<li class="rd-portrait-trait">${escHtml(String(t))}</li>`)
    .join("");
  return (
    `<article class="rd-portrait">${img}` +
    `<div class="rd-portrait-body">` +
    `<h4 class="rd-portrait-name">${escHtml(b.name || "")}</h4>${meta}` +
    (b.html != null || b.text != null || b.definition != null
      ? `<div class="rd-portrait-text">${textHTML(b)}</div>`
      : "") +
    (traits ? `<ul class="rd-portrait-traits">${traits}</ul>` : "") +
    `</div></article>`
  );
};

function section(title: string, cls: string, items: unknown[]): string {
  if (!items.length) return "";
  const lis = items.map((it) => `<li>${itemHTML(it)}</li>`).join("");
  return `<section class="${cls}"><h5 class="${cls}-h">${escHtml(title)}</h5><ol>${lis}</ol></section>`;
}

export const renderArgument: Renderer<BlockMap["argument"]> = (b) => {
  const title = b.title ? `<div class="rd-argument-title">${escHtml(b.title)}</div>` : "";
  const conclusion = b.conclusion != null && b.conclusion !== "" ? itemHTML(b.conclusion) : "";
  return (
    `<div class="rd-argument">${title}` +
    section("مقدمات", "rd-argument-premises", asArray(b.premises)) +
    section("فرض‌ها", "rd-argument-assumptions", asArray(b.assumptions)) +
    (conclusion
      ? `<section class="rd-argument-conclusion"><h5 class="rd-argument-conclusion-h">نتیجه</h5><p>${conclusion}</p></section>`
      : "") +
    `</div>`
  );
};

export const renderProof: Renderer<BlockMap["proof"]> = (b) => {
  const title = b.title ? `<div class="rd-proof-title">${escHtml(b.title)}</div>` : "";
  const steps = asArray(b.steps)
    .map((st) => {
      const reason = st.reason
        ? `<span class="rd-proof-reason">(${escHtml(String(st.reason))})</span>`
        : "";
      const statement =
        st.html != null || st.text != null || st.definition != null
          ? textHTML(st)
          : escHtml(String(st.statement ?? ""));
      return `<li class="rd-proof-step"><span class="rd-proof-statement">${statement}</span>${reason}</li>`;
    })
    .join("");
  return `<div class="rd-proof">${title}<ol class="rd-proof-steps">${steps}</ol></div>`;
};
