import { main } from "../../preferences/prefs.js";
import { after, escHtml, toFa } from "../../core.js";
import { icon } from "../components/icons.js";
import { unitWords } from "../components/unit.js";
import { resolveLabel } from "../../engine/presentation/labels.js";
import { registerSheet, sheetBody } from "../components/sheet.js";
import { BP_SHEET, mqMax } from "../../system/breakpoints";

const _labPhoneMQ = typeof window !== "undefined" && window.matchMedia ? mqMax(BP_SHEET) : null;
export function pageLab() {
  const widgetEntries = Object.entries(CourseRuntime.getWidgets() || {});
  if (!widgetEntries.length) {
    main.innerHTML = `<div class="page"><div class="card" style="padding:24px;text-align:center">ویجتی در این درس تعریف نشده است.</div></div>`;
    return;
  }

  const cards = widgetEntries
    .map(([k, w]) => {
      const sessArr = Array.isArray(w.sess) ? w.sess : [];
      const sessLinks = sessArr
        .map((id) => {
          const ss = ((CourseRuntime.getCourse() || {}).sessions || []).find((x) => x.id === id);
          return ss
            ? `<a onclick="go('s/${id}')" style="cursor:pointer">${unitWords().ezafe} ${toFa(ss.num)}</a>`
            : "";
        })
        .filter(Boolean)
        .join("، ");
      const relatedHTML = sessLinks
        ? ` <span style="color:var(--text-tertiary)">· مرتبط با ${sessLinks}</span>`
        : "";
      return `<div class="widget" id="lab-${escHtml(k)}" data-lab-anchor="${escHtml(k)}">
    <div class="wt"><span class="wt-ic">${icon("flask")}</span><h3>${escHtml(w.title)}</h3></div>
    <div class="wd">${w.desc}${relatedHTML}</div>
    <div data-widget="${escHtml(k)}"></div>
  </div>`;
    })
    .join("");

  const side = widgetEntries
    .map(
      ([k, w], i) => `
  <a class="pss-item" href="#lab-${escHtml(k)}" data-anchor="lab-${escHtml(k)}" data-sheet-close>
    <span class="pss-num">${toFa(i + 1)}</span>
    <span class="pss-body">
      <b>${escHtml(w.title || k)}</b>
      <span class="pss-meta">${Array.isArray(w.sess) && w.sess.length ? "مرتبط با " + toFa(w.sess.length) + " " + unitWords().singular : "بدون ارتباط"}</span>
    </span>
  </a>`,
    )
    .join("");

  main.innerHTML = `<div class="page lab-page">
  <header class="ui-hero lab-hero">
    <span class="lab-kicker">${icon("flask")}${resolveLabel((CourseRuntime.getCourse() || {}).meta, "lab")}</span>
    <h1 class="lab-h1">${escHtml(resolveLabel((CourseRuntime.getCourse() || {}).meta, "lab"))}</h1>
    <p class="lab-sub">${escHtml((CourseRuntime.getCourse() || {}).meta.labSubtitle || "شبیه‌سازی‌های تعاملی درس را خودتان کاوش کنید")}</p>
  </header>
  <div class="pg-mhead-slot"><header class="pg-mhead" aria-label="ناوبری ویجت‌ها">
    <div class="pg-mhead-row">
      <h2 class="pg-mhead-title" data-mhead-title>${escHtml(widgetEntries[0][1].title || "")}</h2>
      <div class="pg-mhead-btns">
        <button type="button" class="pg-mbtn" data-sheet-open="widgets" aria-expanded="false" aria-controls="labSheetWidgets" aria-label="فهرست ویجت‌ها">${icon("list")}<b>${toFa(widgetEntries.length)}</b></button>
      </div>
    </div>
  </header></div>
  <div class="lv-sheet lv-sheet--widgets" id="labSheetWidgets" aria-label="فهرست ویجت‌ها"><div class="lv-sheet-h">${icon("flask")}<span>ویجت‌ها</span></div></div>
  <div class="lab-grid">
    <div class="lab-main">
      <div class="lab-list">${cards}</div>
    </div>
    <aside class="lab-side" aria-label="فهرست ویجت‌ها">
      <div class="pss-card pss-card--toc">
        <div class="pss-head">${icon("flask")}<b>ویجت‌ها</b><span class="pss-count">${toFa(widgetEntries.length)}</span></div>
        <nav class="pss-nav">${side}</nav>
      </div>
    </aside>
  </div>
</div>`;

  after(main);

  (function initLabMobileHead() {
    const head = main.querySelector(".pg-mhead");
    const sheetEl = document.getElementById("labSheetWidgets");
    const card = main.querySelector(".lab-side .pss-card--toc");
    const aside = main.querySelector(".lab-side");
    if (!head || !sheetEl || !card || !aside) return;

    // کارت فهرست: روی موبایل داخل برگه، روی دسکتاپ داخل ستون کناری
    const placeCard = () => {
      const phone = !!(_labPhoneMQ && _labPhoneMQ.matches);
      (phone ? sheetBody(sheetEl) : aside).appendChild(card);
    };

    // هدر ثابت فقط وقتی ویجتی به زیر نوار بالا برسد نشان داده می‌شود و عنوان همان ویجت را دارد
    const sync = () => {
      const phone = !!(_labPhoneMQ && _labPhoneMQ.matches);
      if (!phone) {
        head.classList.remove("is-stuck");
        return;
      }
      const topH = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--topbar-h")) || 64;
      const refLine = topH + head.offsetHeight;
      let cur = null;
      for (const w of main.querySelectorAll(".lab-list .widget")) {
        if (w.getBoundingClientRect().top <= refLine) cur = w;
      }
      head.classList.toggle("is-stuck", !!cur);
      if (cur) {
        const t = cur.querySelector(".wt h3")?.textContent || "";
        const el = head.querySelector("[data-mhead-title]");
        if (el && el.textContent !== t) el.textContent = t;
      }
    };

    let raf = 0;
    const onScroll = () => {
      if (!raf)
        raf = requestAnimationFrame(() => {
          raf = 0;
          sync();
        });
    };
    const unregister = registerSheet("widgets", sheetEl, { portal: true });
    const onMQ = () => {
      placeCard();
      sync();
    };
    placeCard();
    sync();
    window.addEventListener("scroll", onScroll, { passive: true });
    if (_labPhoneMQ) _labPhoneMQ.addEventListener("change", onMQ);

    const prev = window._sessCleanup;
    window._sessCleanup = () => {
      if (prev)
        try {
          prev();
        } catch (_) {}
      window.removeEventListener("scroll", onScroll);
      if (_labPhoneMQ) _labPhoneMQ.removeEventListener("change", onMQ);
      if (raf) cancelAnimationFrame(raf);
      try {
        unregister();
      } catch {
        /* sheet already gone */
      }
      sheetEl.remove();
    };
  })();

  (function initLabScrollSpy() {
    const sidebar = main.querySelector(".lab-side");
    if (!sidebar) return;
    const links = Array.from(sidebar.querySelectorAll(".pss-item[data-anchor]"));
    if (!links.length) return;
    const targets = links.map((a) => document.getElementById(a.dataset.anchor)).filter(Boolean);
    if (!targets.length) return;

    let raf = 0;
    const tick = () => {
      raf = 0;
      const ref = (window.scrollY || document.documentElement.scrollTop) + 140;
      let active = -1;
      for (let i = 0; i < targets.length; i++) {
        if (targets[i].offsetTop <= ref) active = i;
        else break;
      }
      links.forEach((a, i) => a.classList.toggle("on", i === active));
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(tick);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    tick();

    links.forEach((a) =>
      a.addEventListener("click", (e) => {
        const el = document.getElementById(a.dataset.anchor);
        if (!el) return;
        e.preventDefault();
        const off = _labPhoneMQ && _labPhoneMQ.matches ? 128 : 96;
        const y = el.getBoundingClientRect().top + window.scrollY - off;
        window.scrollTo({ top: y, behavior: "smooth" });
      }),
    );

    const prev = window._sessCleanup;
    window._sessCleanup = () => {
      if (prev)
        try {
          prev();
        } catch (_) {}
      window.removeEventListener("scroll", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  })();
}
