// زمان‌بندی مرور فلش‌کارت (Spaced repetition) — توابع خالص، بدون DOM و بدون storage.
//
// این همان منطق زمان‌بندی‌ای است که قبلاً در src/lib/ui/learning/flashcards.js بود
// (_schedule، previews، _retention، _isMastered)، با همان اعداد و همان رفتار.
// یادداشت: این یک SM-2 خالص نیست. چهار درجه (again/hard/good/easy)، ضریب آسانی بین ۱٫۳ و ۳٫۲،
// و شمارندهٔ lapses دارد. نام «SM-2» در roadmap به خانوادهٔ همین الگوریتم اشاره دارد.
//
// قانون‌ها:
//   again : lapses+1، reps=0، ivl=0، آسانی−۰٫۲، موعد ۱۰ دقیقه
//   hard  : آسانی−۰٫۱۵، فاصله×۱٫۲ (حداقل ۱ روز برای اولین بار)
//   good  : اولین بار ۱ روز، دومین بار ۳ روز، بعد ivl×آسانی
//   easy  : آسانی+۰٫۱۵ (سقف ۳٫۲)، فاصلهٔ اولیه ۴ روز، بعد ivl×آسانی×۱٫۳

export type Grade = "again" | "hard" | "good" | "easy";

export const GRADES: readonly Grade[] = Object.freeze(["again", "hard", "good", "easy"] as const);

export const MIN_MS = 60_000;
export const DAY_MS = 86_400_000;

// وضعیت زمان‌بندی یک کارت. هنگام خواندن از localStorage ممکن است فیلدها نباشند.
export interface CardState {
  ease: number;
  ivl: number;
  reps: number;
  lapses: number;
  due: number;
  last: number;
  seen: number;
}

// ورودی جزئی: کارت تازه می‌تواند {} باشد.
export type CardStateInput = Partial<CardState>;

// پیش‌نمایش یک درجه: موعد بعدی و فاصلهٔ آن با «الان» (میلی‌ثانیه).
export interface Preview {
  grade: Grade;
  due: number;
  span: number;
}

// رویداد مرور (همان شکلی که در ذخیرهٔ رویدادها هست).
export interface ReviewEvent {
  t?: unknown;
  result?: unknown;
  ts?: unknown;
}

export const RETENTION_WINDOW = 300;
export const EASE_MIN = 1.3;
export const EASE_MAX_EASY = 3.2;
export const MASTERED_IVL_DAYS = 21;
export const MASTERED_MIN_REPS = 3;

// زمان‌بندی یک مرور. خالص: st را تغییر نمی‌دهد و وضعیت تازه را برمی‌گرداند.
export function schedule(
  st: CardStateInput | null | undefined,
  grade: Grade,
  now: number,
): CardState {
  const base = st || {};
  let ease = base.ease || 2.5;
  let ivl = base.ivl || 0;
  let reps = base.reps || 0;
  let lapses = base.lapses || 0;
  let due: number;

  switch (grade) {
    case "again":
      lapses += 1;
      reps = 0;
      ivl = 0;
      ease = Math.max(EASE_MIN, ease - 0.2);
      due = now + 10 * MIN_MS;
      break;
    case "hard":
      ease = Math.max(EASE_MIN, ease - 0.15);
      ivl = reps === 0 ? 1 : Math.max(1, Math.round(ivl * 1.2));
      reps += 1;
      due = now + ivl * DAY_MS;
      break;
    case "good":
      ivl = reps === 0 ? 1 : reps === 1 ? 3 : Math.max(2, Math.round(ivl * ease));
      reps += 1;
      due = now + ivl * DAY_MS;
      break;
    case "easy":
      ease = Math.min(EASE_MAX_EASY, ease + 0.15);
      ivl = reps === 0 ? 4 : Math.max(3, Math.round(ivl * ease * 1.3));
      reps += 1;
      due = now + ivl * DAY_MS;
      break;
  }

  return { ease, ivl, reps, lapses, due, last: now, seen: (base.seen || 0) + 1 };
}

// پیش‌نمایش هر چهار درجه برای نمایش «دوباره در ۱۰ دقیقه / ۳ روز / …».
export function previews(
  st: CardStateInput | null | undefined,
  now: number = Date.now(),
): Preview[] {
  return GRADES.map((grade) => {
    const due = schedule(st, grade, now).due;
    return { grade, due, span: due - now };
  });
}

// درصد پاسخ‌های «خوب» و «آسان» در آخرین ۳۰۰ مرور فلش‌کارت. اگر مروری نباشد null.
export function retention(
  events: readonly ReviewEvent[],
  window: number = RETENTION_WINDOW,
): number | null {
  const flashes = events.filter((e) => e && e.t === "flash").slice(-window);
  if (!flashes.length) return null;
  const ok = flashes.filter((e) => e.result === "good" || e.result === "easy").length;
  return Math.round((ok / flashes.length) * 100);
}

// کارت «یادگرفته‌شده» است اگر فاصله‌اش به ۲۱ روز برسد و حداقل سه بار درست مرور شده باشد.
export function isMastered(st: CardStateInput | null | undefined): boolean {
  return !!st && (st.ivl ?? 0) >= MASTERED_IVL_DAYS && (st.reps ?? 0) >= MASTERED_MIN_REPS;
}

// ─── پخش مجدد شواهد (SM-2 کلاسیک) ───────────────────────────────────────────
//
// نویسندهٔ واحد الگوریتم زمان‌بندی همین فایل است:
//   - schedule / previews / retention / isMastered : زمان‌بندی چهاردرجه‌ای فلش‌کارت (UI مرور)
//   - replay : SM-2 کلاسیک با ضریب آسانی EF، برای «پخش مجدد» شواهد تمرین/مرور در مدل تسلط.
// هر دو از یک ثابت روز (DAY_MS) استفاده می‌کنند و خالص‌اند: بدون DOM و بدون storage.

// شاهد ورودی پخش مجدد: زمان (ms) و کیفیت ۰..۱.
export interface ReplayEvidence {
  at: number;
  q: number;
}

// خروجی پخش مجدد: همان شکلی که مدل تسلط در UnitState ذخیره می‌کند.
export interface ReplayState {
  ease: number;
  reps: number;
  ivl: number;
  lastAt: number | null;
  nextDueAt: number | null;
}

function sortByTime<T extends { at: number }>(evidence: readonly T[]): T[] {
  return evidence.slice().sort((a, b) => a.at - b.at);
}

// زمان‌بندی SM-2 ساده، با پخش مجدد شواهد به ترتیب زمان. خالص و قابل بازتولید.
export function replay(evidence: readonly ReplayEvidence[]): ReplayState {
  const ev = sortByTime(evidence);
  let ease = 2.5;
  let reps = 0;
  let ivl = 0;
  let lastAt: number | null = null;
  ev.forEach((e) => {
    const q5 = Math.round(e.q * 5);
    if (q5 >= 3) {
      reps += 1;
      ivl = reps === 1 ? 1 : reps === 2 ? 3 : Math.max(1, Math.round(ivl * ease));
    } else {
      reps = 0;
      ivl = 1;
    }
    ease = Math.max(1.3, ease + (0.1 - (5 - q5) * (0.08 + (5 - q5) * 0.02)));
    lastAt = e.at;
  });
  return {
    ease,
    reps,
    ivl,
    lastAt,
    nextDueAt: lastAt == null ? null : lastAt + ivl * DAY_MS,
  };
}
