(function () {
  "use strict";
  const R = 8.314; // J/(mol·K)
  const MAXS = 3 * R * Math.log(4); // مقیاس نوار: n = 3، V₂/V₁ = 4

  const W = {
    title: "ماشین‌حساب انبساط آزادانه",
    desc: "حجم نهایی و شمار مول را تغییر بده. دما ثابت است و هیچ کار یا گرمایی مبادله نمی‌شود؛ ظاهر گاز هم تغییری نمی‌کند.",
    mount(box) {
      box.innerHTML =
        '<div style="font-family:inherit">' +
        '<label style="display:block;font-size:13px">نسبت حجم V₂/V₁: <strong data-r-out>2.0</strong>' +
        '<input type="range" min="1" max="4" step="0.1" value="2" data-ratio style="width:100%;margin-top:6px"></label>' +
        '<label style="display:block;font-size:13px;margin-top:10px">شمار مول n: <strong data-n-out>1</strong>' +
        '<input type="range" min="1" max="3" step="1" value="1" data-n style="width:100%;margin-top:6px"></label>' +
        '<div data-ds style="font-size:30px;font-weight:700;margin:14px 0 6px;font-variant-numeric:tabular-nums" dir="ltr"></div>' +
        '<div data-f style="font-size:12px;opacity:.75;direction:ltr;text-align:start" dir="ltr"></div>' +
        '<div style="height:12px;margin-top:12px;border-radius:99px;background:var(--surface-subtle);overflow:hidden">' +
        '<i data-bar style="display:block;height:100%;width:0;border-radius:99px;background:var(--accent);transition:width .25s ease"></i></div>' +
        '<div style="font-size:11px;opacity:.6;margin-top:8px">ظاهر سامانه: ثابت · تعداد ریزحالت‌های در دسترس: بیشتر</div>' +
        "</div>";

      const ratio = box.querySelector("[data-ratio]");
      const n = box.querySelector("[data-n]");
      const rOut = box.querySelector("[data-r-out]");
      const nOut = box.querySelector("[data-n-out]");
      const ds = box.querySelector("[data-ds]");
      const f = box.querySelector("[data-f]");
      const bar = box.querySelector("[data-bar]");

      function render() {
        const r = Number(ratio.value);
        const k = Number(n.value);
        const dS = k * R * Math.log(r);
        rOut.textContent = r.toFixed(1);
        nOut.textContent = String(k);
        ds.textContent = "ΔS = +" + dS.toFixed(2) + " J/K";
        f.textContent = "ΔS = n·R·ln(V₂/V₁) = " + k + " × 8.314 × ln(" + r.toFixed(1) + ")";
        bar.style.width = Math.max(2, (dS / MAXS) * 100) + "%";
      }
      ratio.addEventListener("input", render);
      n.addEventListener("input", render);
      render();
    },
    unmount(box) {
      box.innerHTML = "";
    },
  };

  CourseRuntime.registerPackSource("entropy-metaphor", { widgets: { "entropy-calc": W } });
})();
