import { escHtml } from "../engine/blocks/escape.js";

// markdown درون‌خطی برای متن انتشار (CHANGELOG) — بدون وابستگی به DOM تا قابل تست باشد.
// `code`، **پررنگ**، __پررنگ__، *کج*، _کج_ و [متن](https://…)
// اول کد جدا می‌شود، بعد escape، بعد قالب‌ها؛ پس محتوای کد و HTML خام اجرا نمی‌شود.

export function mdInline(s) {
  const codes = [];
  let t = String(s == null ? "" : s).replace(/`([^`]+)`/g, (_, c) => {
    codes.push(c);
    return "\u0000" + (codes.length - 1) + "\u0000";
  });
  t = escHtml(t)
    .replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>')
    .replace(/\*\*([^*\n]+?)\*\*/g, "<strong>$1</strong>")
    .replace(/__([^_\n]+?)__/g, "<strong>$1</strong>")
    .replace(/(^|[^\w*])\*(?!\s)([^*\n]+?)\*(?![\w*])/g, "$1<em>$2</em>")
    .replace(/(^|[^\w])_(?!\s)([^_\n]+?)_(?!\w)/g, "$1<em>$2</em>");
  return t.replace(/\u0000(\d+)\u0000/g, (_, i) => "<code>" + escHtml(codes[+i]) + "</code>");
}
