// مدل اعلان‌ها: شناسه، خوانده‌شده و حذف‌شده — بدون DOM تا قابل تست باشد.
// قانون‌ها:
//  - شناسه قبل از فیلتر تعیین می‌شود (وگرنه حذف‌شده‌ها پنهان نمی‌شوند)
//  - به‌روزرسانی هرگز خوانده یا حذف‌شده حساب نمی‌شود تا اعمال شود
//  - «همه خوانده شد» با readAllAt همهٔ اعلان‌های قدیمی‌تر را خوانده می‌کند

export function notifId(it) {
  return it.id || it.kind + ":" + it.title + ":" + it.ts;
}

export function applyNotifState(items, { dismissed = new Set(), read = new Set(), readAllAt = 0 } = {}) {
  return items
    .map((it) => ({ ...it, id: notifId(it) }))
    .filter((it) => it.kind === "update" || !dismissed.has(it.id))
    .map((it) => ({
      ...it,
      unread: it.kind === "update" || (!read.has(it.id) && !(it.ts <= readAllAt)),
    }));
}
