import { $, reRenderMmd, toast } from "../../core.js";
import { setPref, applyPrefs } from "../../preferences/prefs.js";
import { applyBrand } from "../../brand.js";
import { go, refreshShellSidebar } from "../layout/router.js";

// ─── هاب مرکزی «کیت UI» ─────────────────────────────────────────────────────
//
// سازنده‌های مشترک نشانه‌گذاری صفحه‌ها. هر واریانت، کلاس و تفاوت‌های بصری خودش را
// می‌فرستد تا خروجی دقیقاً مثل قبل باشد؛ فقط نویسندهٔ markup یکی می‌شود.

/**
 * رینگ پیشرفت SVG — تک‌نویسندهٔ ۴ رینگ قبلی (problems/progress/shell/router).
 * size/c/r هندسه؛ bgClass/fgClass/fgId کلاس و شناسه؛ bgAttrs/fgAttrs بقیهٔ attributeها؛
 * defs و defsFirst جای بلوک gradient؛ svgAttrs برای attributeهای خود <svg>.
 */
export function svgRing(o) {
  const size = o.size;
  const c = o.c != null ? o.c : size / 2;
  const r = o.r;
  const svgAttrs = Object.entries(o.svgAttrs || {})
    .map(([k, v]) => ` ${k}="${v}"`)
    .join("");
  const defs = o.defs || "";
  const defsFirst = o.defsFirst !== false;
  const cls = (name, val) => (val ? ` ${name}="${val}"` : "");
  const bg = o.noBg
    ? ""
    : `<circle${cls("class", o.bgClass)}${cls("id", o.bgId)} cx="${c}" cy="${c}" r="${r}"${o.bgAttrs || ""}/>`;
  const fg = `<circle${cls("class", o.fgClass)}${cls("id", o.fgId)} cx="${c}" cy="${c}" r="${r}"${o.fgAttrs || ""}/>`;
  return `<svg${svgAttrs}>${defsFirst ? defs : ""}${bg}${fg}${defsFirst ? "" : defs}</svg>`;
}

// ─── هاب مرکزی «فلو فعال‌سازی پک» ──────────────────────────────────────────
//
// یک بار نوشته‌شده: فعال‌سازی (Loader یا موتور) → برند → پرف‌ها → سایدبار → ناوبری/بازرسم →
// toast خطای واحد. کپی‌های قبلی در library.js، pack.js، router.js و mount.ts به همین دو تابع
// همگرا شده‌اند.

// مسیر کلیک‌ها (ناهمگام، با Loader): بعد از فعال‌سازی، `after` اجرا می‌شود؛
// اگر `after` داده نشود به صفحهٔ پک می‌رود. خروجی: موفقیت فعال‌سازی.
export async function activatePackAndNavigate(id, after) {
  try {
    if (typeof Loader !== "undefined" && typeof Loader.activate === "function") {
      await Loader.activate(id);
      applyBrand();
    } else {
      CourseRuntime.activatePack(id);
    }
    if (typeof applyPrefs === "function") applyPrefs();
    refreshShellSidebar();
    if (typeof after === "function") after();
    else go("p/" + encodeURIComponent(id));
    return true;
  } catch (_) {
    if (typeof toast === "function") toast("فعال‌سازی ناموفق بود", "err");
    return false;
  }
}

// مسیر همگام (روتر و اجرای اول): فقط با موتور، بدون toast؛ روتر بعدش مسیر را خودش می‌کشد.
export function activatePackSync(id) {
  let ok = false;
  try {
    ok = !!CourseRuntime.activatePack(id);
  } catch (_) {
    ok = false;
  }
  if (ok) {
    if (typeof applyPrefs === "function") applyPrefs();
    if (typeof applyBrand === "function") applyBrand();
    if (typeof refreshShellSidebar === "function") refreshShellSidebar();
  }
  return ok;
}

// [حذف‌شده] نویسندهٔ مردهٔ تم (#themeToggle): شل این دکمه را hidden می‌کند و onclick را null
// می‌کند (shell.js)؛ تنها نویسندهٔ تم، رجیستری تنظیمات است (setPref → applyPrefs) و آیکن
// همان دکمه هم از applyPrefs همگام می‌شود.

export function _packReadCount(packId, sessions) {
  if (!sessions || !sessions.length) return 0;
  try {
    const key = packId + "Read";
    const raw = localStorage.getItem(key);
    if (!raw) return 0;
    const arr = JSON.parse(raw);
    if (!Array.isArray(arr)) return 0;
    const set = new Set(arr);
    return sessions.filter((s) => set.has(s.id)).length;
  } catch (_) {
    return 0;
  }
}

(function () {
  if (document.getElementById("fpop")) return;
  const pop = document.createElement("div");
  pop.id = "fpop";
  pop.innerHTML =
    '<div class="fp-t"></div><div class="fp-x" dir="ltr"></div><div class="fp-u"></div>';
  document.body.appendChild(pop);
  const fpT = pop.querySelector(".fp-t"),
    fpX = pop.querySelector(".fp-x"),
    fpU = pop.querySelector(".fp-u");

  function show(c) {
    const s = ((CourseRuntime.getCourse() || {}).sessions || []).find((x) => x.id === c.dataset.s);
    const i = s ? s.formulas.findIndex((f) => f.t === c.dataset.t) : -1;
    if (!s || i < 0) {
      pop.style.display = "none";
      return;
    }
    const f = s.formulas[i];
    fpT.textContent = f.t;
    if (window.katex) katex.render(f.tex, fpX, { displayMode: true, throwOnError: false });
    else fpX.textContent = f.tex;
    fpU.textContent = (f.use ? f.use + " · " : "") + "کلیک کنید";
    if (window.renderMathInElement) {
      renderMathInElement(fpU, {
        delimiters: [{ left: "$", right: "$", display: false }],
        throwOnError: false,
      });
    }
    pop.style.display = "block";
    const z = parseFloat(getComputedStyle(document.documentElement).zoom) || 1;
    const r = c.getBoundingClientRect(),
      pr = pop.getBoundingClientRect();
    const rw = pr.width / z,
      rh = pr.height / z,
      vw = innerWidth / z,
      vh = innerHeight / z;
    const x = Math.min(Math.max(8, (r.left + r.width / 2) / z - rw / 2), vw - rw - 8);
    let y = r.bottom / z + 10;
    if (y + rh > vh - 8) y = r.top / z - rh - 10;
    pop.style.left = x + "px";
    pop.style.top = y + "px";
  }

  document.addEventListener("mouseover", (e) => {
    const c = e.target.closest(".fchip");
    if (c) show(c);
  });

  document.addEventListener("mouseout", (e) => {
    if (e.target.closest(".fchip") && !("ontouchstart" in window)) pop.style.display = "none";
  });

  window.addEventListener("scroll", () => (pop.style.display = "none"), { passive: true });

  let _fpTouchT = 0;
  document.addEventListener("click", (e) => {
    const c = e.target.closest(".fchip");
    if (!c) {
      if (!e.target.closest("#fpop")) pop.style.display = "none";
      return;
    }
    const now = Date.now();
    const s = ((CourseRuntime.getCourse() || {}).sessions || []).find((x) => x.id === c.dataset.s);
    const i = s ? s.formulas.findIndex((f) => f.t === c.dataset.t) : -1;
    if (i < 0) return;
    if (!("ontouchstart" in window) && matchMedia("(hover:hover)").matches) {
      go("s/" + s.id, "f-" + s.id + "-" + i);
      return;
    }
    if (
      pop.style.display === "block" &&
      pop.dataset.fid === c.dataset.s + ":" + c.dataset.t &&
      now - _fpTouchT < 2000
    ) {
      go("s/" + s.id, "f-" + s.id + "-" + i);
      pop.style.display = "none";
      return;
    }
    show(c);
    pop.dataset.fid = c.dataset.s + ":" + c.dataset.t;
    _fpTouchT = now;
  });
})();
