// Drag-to-dismiss for phone bottom sheets (touch only).
// A drag starts on the handle (top HANDLE_ZONE px of the sheet), or anywhere on the sheet
// while its scrolling list is at the top. The sheet follows the finger; it closes past 30%
// of its height or on a quick flick, otherwise it springs back.
const BOUND = new WeakSet();
const HANDLE_ZONE = 36;
const SNAP_MS = 280;

function listScrollTop(sheet) {
  for (const el of sheet.querySelectorAll("*")) {
    const cs = getComputedStyle(el);
    if ((cs.overflowY === "auto" || cs.overflowY === "scroll") && el.scrollHeight > el.clientHeight + 1) {
      return el.scrollTop;
    }
  }
  return 0;
}

export function attachSheetDrag(sheet, { isOpen, requestClose }) {
  if (!sheet || BOUND.has(sheet)) return;
  BOUND.add(sheet);

  let tracking = false;
  let dragging = false;
  let y0 = 0;
  let dy = 0;
  let t0 = 0;
  let height = 0;
  const reset = () => {
    tracking = false;
    dragging = false;
  };

  sheet.addEventListener(
    "touchstart",
    (e) => {
      if (!isOpen() || e.touches.length !== 1) return reset();
      const r = sheet.getBoundingClientRect();
      const y = e.touches[0].clientY;
      const inHandle = y - r.top <= HANDLE_ZONE;
      if (!inHandle && listScrollTop(sheet) > 0) return reset();
      tracking = true;
      dragging = false;
      y0 = y;
      dy = 0;
      t0 = performance.now();
      height = r.height;
    },
    { passive: true }
  );

  sheet.addEventListener(
    "touchmove",
    (e) => {
      if (!tracking) return;
      const d = e.touches[0].clientY - y0;
      if (!dragging) {
        if (d < -4) return reset(); // upward gesture: leave it to the list
        if (d < 8) return; // jitter
        dragging = true;
        sheet.style.transition = "none";
      }
      e.preventDefault(); // keep the page and list still while the sheet follows the finger
      dy = Math.max(0, d);
      sheet.style.transform = `translateY(${dy}px)`;
    },
    { passive: false }
  );

  const end = () => {
    if (!tracking || !dragging) return reset();
    const velocity = dy / Math.max(1, performance.now() - t0); // px per ms
    const dismiss = dy > Math.max(60, height * 0.3) || (velocity > 0.6 && dy > 40);
    reset();
    sheet.style.transition = `transform ${SNAP_MS}ms var(--ease-std, ease)`;
    if (dismiss) {
      sheet.style.transform = "translateY(100%)";
      setTimeout(() => {
        requestClose();
        sheet.style.transform = "";
        sheet.style.transition = "";
      }, SNAP_MS);
    } else {
      sheet.style.transform = "";
      setTimeout(() => {
        sheet.style.transition = "";
      }, SNAP_MS);
    }
  };
  sheet.addEventListener("touchend", end, { passive: true });
  sheet.addEventListener("touchcancel", end, { passive: true });
}
