// نام واحد درسی پک (جلسه، فصل، …) برای متن‌های رابط کاربری (Phase 6.9).
// هر فراخوانی از درس فعلی می‌خواند، پس با عوض شدن پک متن‌ها هم عوض می‌شوند.
import { unitName } from "../../engine/presentation/labels.js";

export function unitWords() {
  const rt = globalThis.CourseRuntime;
  const course = rt && typeof rt.getCourse === "function" ? rt.getCourse() : null;
  return unitName(course && course.meta);
}
