// letters.ts — الفبای واحد گزینه‌های چندگزینه‌ای.
// هاب مرکزی «لایهٔ لیبل»: هم رندرر بلوک‌های موتور (quiz) و هم صفحهٔ تمرین از همین
// آرایه می‌خوانند تا گزینه‌ها در کل اپ با یک الفبای فارسی نام‌گذاری شوند.

export const MCQ_LETTERS: readonly string[] = Object.freeze([
  "A",
  "B",
  "C",
  "D",
  "E",
  "F",
]);

/** حرف گزینهٔ i-ام؛ اگر از الفبا بیرون بزد، شمارهٔ فارسی‌شده. */
export function mcqLetter(i: number): string {
  return MCQ_LETTERS[i] ?? String(i + 1);
}
