// یک منطق برای همهٔ منوهای پایینی موبایل: فهرست جلسات، فهرست بخش‌ها، پیشرفت و دفتر اشتباهات.
// هر منو یک عنصر با کلاس .lv-sheet است و باز بودنش فقط با کلاس .is-open مشخص می‌شود.
// دکمهٔ بازکردن هر منو: data-sheet-open="<id>"؛ گزینه‌هایی که بعد از انتخاب باید بسته شوند: data-sheet-close.
// قانون‌ها: هم‌زمان فقط یک منو باز است؛ کلیک بیرون، پرده یا Escape آن را می‌بندد؛ روی گوشی با کشیدن پایین بسته می‌شود.
import { attachSheetDrag } from "./sheet-drag.js";
import { BP_SHEET, mqMax } from "../../system/breakpoints";
// رجیستری واحد overlay (هاب system/overlay-stack.js): برگه‌های پایینی هم در استک ثبت می‌شوند
import { _ovDetach, _ovOpen } from "../../system/overlay-stack.js";

const phoneMQ = mqMax(BP_SHEET);
const sheets = new Map(); // id -> { el, portal, drop, onOpen, onClose }
let scrim = null;
let wired = false;

const isPhone = () => phoneMQ.matches;
const chromeHost = () => document.getElementById("lector-chrome") || document.body;
const triggersOf = (id) => document.querySelectorAll(`[data-sheet-open="${id}"]`);

// بدنهٔ قابل‌اسکرول هر برگه: سربرگ (.lv-sheet-h) ثابت می‌ماند و فقط بدنه بالا و پایین می‌رود
export function sheetBody(el) {
  let body = el.querySelector(":scope > .lv-sheet-body");
  if (!body) {
    body = document.createElement("div");
    body.className = "lv-sheet-body";
    el.appendChild(body);
  }
  return body;
}

function wrapBody(el) {
  const body = sheetBody(el);
  [...el.childNodes].forEach((n) => {
    if (n === body) return;
    if (n.nodeType === 1 && n.classList.contains("lv-sheet-h")) return;
    body.appendChild(n);
  });
}

function prune() {
  for (const [id, s] of sheets) if (!s.el.isConnected) sheets.delete(id);
}

export function isSheetOpen(id) {
  return !!sheets.get(id)?.el.classList.contains("is-open");
}

// پرده باید در همان میزبان برگه‌ها باشد؛ اگر در body بماند، روی برگه و تب‌بار می‌نشیند
function getScrim() {
  const host = chromeHost();
  if (!scrim || !scrim.isConnected || scrim.parentElement !== host) {
    if (scrim) scrim.remove();
    scrim = document.createElement("div");
    scrim.className = "lv-sheet-scrim";
    scrim.hidden = true;
    host.appendChild(scrim);
  }
  return scrim;
}

function syncScrim() {
  const anyOpen = [...sheets.values()].some((s) => s.el.classList.contains("is-open"));
  getScrim().hidden = !(isPhone() && anyOpen);
}

function syncTriggers(id) {
  const open = isSheetOpen(id);
  triggersOf(id).forEach((t) => {
    t.setAttribute("aria-expanded", open ? "true" : "false");
    t.classList.toggle("on", open);
  });
}

// منوی دسکتاپ زیر دکمه‌اش، هم‌لبه با لبهٔ راست دکمه (RTL)
function placeDrop(s) {
  const trig = triggersOf(s.id)[0];
  if (!trig) return;
  const r = trig.getBoundingClientRect();
  s.el.style.position = "fixed";
  s.el.style.top = Math.round(r.bottom) + "px"; // flush under the trigger, no gap
  s.el.style.left = "auto";
  s.el.style.right = Math.round(window.innerWidth - r.right) + "px";
  // fit the menu to its content: a short list must not leave an empty box, a long one scrolls within 70vh / 440px
  s.el.style.height = "auto";
  const want = s.el.scrollHeight;
  const cap = Math.min(Math.round(window.innerHeight * 0.7), 440, Math.max(160, window.innerHeight - r.bottom - 24));
  s.el.style.height = Math.min(want, cap) + "px";
}

function place(id) {
  const s = sheets.get(id);
  if (!s) return;
  const el = s.el;
  // a drop menu stays anchored under its button on any screen at least 520px wide (4:3 projectors included)
  if (isPhone() && !(s.drop && window.innerWidth >= 520)) {
    el.classList.remove("lv-sheet--drop");
    el.style.position = "";
    el.style.top = "";
    el.style.left = "";
    el.style.right = "";
    if (s.portal && el.parentElement !== chromeHost()) chromeHost().appendChild(el);
  } else if (s.drop) {
    el.classList.add("lv-sheet--drop");
    if (el.parentElement !== document.body) document.body.appendChild(el);
    placeDrop(s);
  }
}

// ثبت یک منو. برگشتی: تابع حذف
export function registerSheet(id, el, opts = {}) {
  if (!el) return () => {};
  prune();
  sheets.set(id, { id, el, portal: !!opts.portal, drop: !!opts.drop, onOpen: opts.onOpen, onClose: opts.onClose });
  el.classList.add("lv-sheet");
  wrapBody(el);
  el.dataset.sheet = id;
  el.setAttribute("role", "dialog");
  attachSheetDrag(el, { isOpen: () => el.classList.contains("is-open"), requestClose: () => closeSheet(id) });
  wire();
  place(id);
  syncTriggers(id);
  syncScrim();
  return () => {
    if (sheets.get(id)?.el === el) {
      closeSheet(id);
      sheets.delete(id);
    }
  };
}

// ورودی استک وقتی حداقل یک برگه باز است؛ با بسته‌شدن همهٔ برگه‌ها از استک درمی‌آید
let _sheetOvEntry = null;

function _syncSheetEntry() {
  const anyOpen = [...sheets.values()].some((s) => s.el.classList.contains("is-open"));
  if (anyOpen && !_sheetOvEntry) {
    _sheetOvEntry = _ovOpen(() => closeAllSheets(), { lock: false, hist: false });
  } else if (!anyOpen && _sheetOvEntry) {
    const entry = _sheetOvEntry;
    _sheetOvEntry = null;
    _ovDetach(entry, true);
  }
}

export function openSheet(id) {
  prune();
  const s = sheets.get(id);
  if (!s) return;
  for (const k of [...sheets.keys()]) if (k !== id) closeSheet(k);
  place(id);
  s.el.classList.add("is-open");
  syncTriggers(id);
  syncScrim();
  _syncSheetEntry();
  s.onOpen?.(s.el);
  // a drop opens while the page may still be scrolling to bring its trigger to the top: keep it attached until the scroll settles
  if (s.drop) {
    const t0 = performance.now();
    const follow = () => {
      if (!s.el.classList.contains("is-open") || performance.now() - t0 > 1600) return;
      placeDrop(s);
      requestAnimationFrame(follow);
    };
    requestAnimationFrame(follow);
  }
}

export function closeSheet(id) {
  const s = sheets.get(id);
  if (!s || !s.el.classList.contains("is-open")) return;
  s.el.classList.remove("is-open");
  syncTriggers(id);
  syncScrim();
  s.onClose?.(s.el);
  _syncSheetEntry();
}

export function toggleSheet(id) {
  if (isSheetOpen(id)) closeSheet(id);
  else openSheet(id);
}

export function closeAllSheets() {
  for (const k of [...sheets.keys()]) closeSheet(k);
}

// دکمهٔ داخل بدنهٔ صفحه (نه نوار ثابت): اول صفحه تا سربرگ ثابت پایین بیاید، بعد برگه باز شود
function scrollThenOpen(id, anchor) {
  // جای چسبیدن واقعی را از سبک محاسبه‌شده می‌خوانیم (sticky top)، نه از یک عدد ثابت
  const stuckTop = parseFloat(getComputedStyle(anchor).top);
  if (!Number.isNaN(stuckTop) && getComputedStyle(anchor).position.includes("sticky")) {
    anchor.style.scrollMarginTop = stuckTop + "px";
  }
  const want = parseFloat(getComputedStyle(anchor).scrollMarginTop) || 0;
  if (Math.abs(anchor.getBoundingClientRect().top - want) < 4) return openSheet(id);
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  anchor.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
  // scrollend زودتر از پایان واقعی انیمیشن می‌آید؛ تا وقتی سرفصل تکان می‌خورد صبر می‌کنیم
  const t0 = performance.now();
  let last = NaN;
  let still = 0;
  const tick = () => {
    const top = anchor.getBoundingClientRect().top;
    still = Math.abs(top - last) < 0.5 ? still + 1 : 0;
    last = top;
    if ((still >= 3 && Math.abs(top - want) <= 4) || performance.now() - t0 > 1200) {
      return openSheet(id);
    }
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

function wire() {
  if (wired) return;
  wired = true;
  document.addEventListener("click", (e) => {
    const t = e.target;
    if (!(t instanceof Element)) return;
    const trig = t.closest("[data-sheet-open]");
    if (trig) {
      const id = trig.dataset.sheetOpen;
      if (!sheets.has(id)) return;
      const anchor = trig.closest("[data-sheet-anchor]");
      if (isPhone() && anchor && !trig.closest(".pg-mhead") && !isSheetOpen(id)) {
        scrollThenOpen(id, anchor);
        return;
      }
      toggleSheet(id);
      return;
    }
    const sheetEl = t.closest(".lv-sheet");
    if (sheetEl && t.closest("[data-sheet-close]")) {
      closeSheet(sheetEl.dataset.sheet);
      return;
    }
    if (!t.closest(".lv-sheet.is-open")) closeAllSheets();
  });
  // Esc برگه‌ها از رجیستری واحد overlay می‌آید (روترین overlay) — کد مستقل حذف شد
  const reflow = () => {
    for (const s of sheets.values()) if (s.drop && s.el.classList.contains("is-open")) placeDrop(s);
  };
  window.addEventListener("resize", reflow, { passive: true });
  // capture: scroll inside any container (not only the window) keeps a drop menu attached to its trigger
  document.addEventListener("scroll", reflow, { passive: true, capture: true });
  phoneMQ.addEventListener?.("change", () => {
    closeAllSheets();
    for (const id of sheets.keys()) place(id);
  });
}
