<script lang="ts">
  // ریشهٔ چیدمان (Phase 7.1). تعیین می‌کند گوشی یا غیر گوشی است و نوار تب را فقط روی گوشی نشان می‌دهد.
  // نوار کناری و نوار بالا همچنان از shell.js می‌آیند؛ این کامپوننت فقط تصمیم چیدمان را نگه می‌دارد.
  import { onMount } from "svelte";
  import { PHONE_MEDIA_QUERY, layoutForWidth, type LayoutKind } from "./layout-switch";
  import LayoutMobile from "./LayoutMobile.svelte";

  let layout = $state<LayoutKind>("desktop");

  onMount(() => {
    const mq = window.matchMedia(PHONE_MEDIA_QUERY);
    const sync = () => {
      layout = layoutForWidth(window.innerWidth);
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  });

  $effect(() => {
    document.documentElement.dataset.layout = layout;
  });
</script>

{#if layout === "phone"}
  <LayoutMobile />
{/if}
