// overlay-stack.js — هاب مرکزی «استک Overlay واحد».
//
// یک رجیستری برای همهٔ overlayهای اپ: یک Esc (فقط روترین overlay بسته می‌شود)،
// یک قفل اسکرول شمارشی (has-overlay)، و یکپارچه‌سازی تاریخچه برای دکمهٔ بازگشت.
// این ماژول زیرلایهٔ UI است: به core.js و router.js وابسته نیست تا زنجیرهٔ import نسازد؛
// router.js همین‌ها را re-export می‌کند و سیستم‌های قدیمی مسیر import قبلی را دارند.
//
// هر ورودی استک:
//   close — بستن overlay (پاک‌سازی DOM و وضعیت خود سیستم)
//   esc   — رفتار اختصاصی Esc (مثل «برگشت از جزئیات» در شیت تنظیمات)؛ پیش‌فرض همان close
//   lock  — قفل اسکرول با has-overlay (پیش‌فرض true برای مودال‌ها؛ منوهای سبک false می‌دهند)
//   hist  — ثبت history برای دکمهٔ بازگشت (پیش‌فرض true؛ منوهای سبک false می‌دهند)

export let _ovPushed = false;
export let _ovSelfBack = false;
export const _ovStack = [];

// تعداد ورودی‌های قفل‌کنندهٔ اسکرول در استک
let _ovLockedCount = 0;

export function _ovLockScroll() {
  document.documentElement.classList.add("has-overlay");
  document.body.classList.add("has-overlay");
}
export function _ovUnlockScroll() {
  document.documentElement.classList.remove("has-overlay");
  document.body.classList.remove("has-overlay");
  try {
    document.documentElement.style.overflow = "";
    document.body.style.overflow = "";
  } catch (_) {}
}

/** آزادسازی قفل اسکرول وقتی هیچ overlay واقعی باز نیست (رفع گیر موبایل) */
export function _ovReconcile() {
  const sb = document.getElementById("sidebar");
  const sbOpen = !!(sb && sb.classList.contains("open"));
  const setOpen = document.body.classList.contains("set-sheet-open");
  const drawerOpen = document.body.classList.contains("drawer-open");
  const modalOpen = !!document.querySelector(
    ".hm-modal-back.open, .set-sheet-back.open, #dtpBack.open, #hmModalBack.open",
  );
  const scrimOn = !!document.querySelector("#shellScrim.on, .scrim.on");
  const pal = document.getElementById("palette");
  const palOpen = !!(pal && (pal.classList.contains("on") || pal.classList.contains("closing")));

  if (sbOpen || setOpen || drawerOpen || modalOpen || scrimOn || palOpen) return;

  if (_ovStack.length) _ovStack.length = 0;
  _ovPushed = false;
  _ovLockedCount = 0;
  _ovUnlockScroll();
  document.documentElement.classList.remove("pal-lock");
}

export function _ovOpen(closeFn, opts) {
  const o = opts || {};
  const entry = {
    close: typeof closeFn === "function" ? closeFn : null,
    esc: typeof o.esc === "function" ? o.esc : null,
    lock: o.lock !== false,
    hist: o.hist !== false,
  };
  _ovStack.push(entry);
  if (entry.lock && _ovLockedCount === 0) _ovLockScroll();
  if (entry.lock) _ovLockedCount++;
  if (entry.hist && !_ovPushed) {
    _ovPushed = true;
    try {
      history.pushState({ opticsOverlay: 1 }, "");
    } catch (_) {}
  }
  return entry;
}

// آزادسازی وضعیت استک بعد از خروج یک ورودی. selfBack یعنی مسیر بستن کلیک کاربر بود
// (دکمهٔ بازگشت مرورگر هم باید برود عقب)؛ silent یعنی بی‌صدا (replaceState).
function _ovRelease(selfBack, keepState) {
  if (!_ovStack.some((en) => en.lock)) {
    if (_ovLockedCount !== 0) {
      _ovLockedCount = 0;
      _ovUnlockScroll();
    }
  }
  if (_ovStack.length === 0 && _ovPushed) {
    _ovPushed = false; // همیشه ریست شود تا باگ پرتاپ شدن رخ ندهد
    if (!keepState) {
      if (selfBack) {
        _ovSelfBack = true;
        try { history.back(); } catch (_) {}
      } else {
        try { history.replaceState(null, ""); } catch (_) {}
      }
    } else {
      try { history.replaceState(null, ""); } catch (_) {}
    }
  }
}

/** بستن روترین overlay (مسیر Esc و دکمهٔ بازگشت مرورگر). */
export function _ovClose(silent, keepState) {
  const top = _ovStack.pop();
  if (top && top.close) top.close();
  _ovRelease(!silent, keepState);
}

/** حذف ورودی مشخص وقتی سیستم خودش با دکمه/کلیک بیرون بسته می‌شود و ممکن است توپ استک نباشد. */
export function _ovRemove(entry, silent, keepState) {
  if (!entry) return;
  const i = _ovStack.indexOf(entry);
  if (i >= 0) _ovStack.splice(i, 1);
  if (entry.close) entry.close();
  _ovRelease(!silent, keepState);
}

/** جداکردن ورودی بدون اجرای close (وقتی سیستم خودش پاک‌سازی را انجام می‌دهد). */
export function _ovDetach(entry, silent, keepState) {
  if (!entry) return;
  const i = _ovStack.indexOf(entry);
  if (i < 0) return;
  _ovStack.splice(i, 1);
  _ovRelease(!silent, keepState);
}

// Esc واحد: فقط روترین overlay بسته می‌شود و تودرتوها نمی‌سوزند.
// اگر یک <dialog> بومی باز باشد، Esc مال خودش است.
function _ovEscKey(e) {
  if (e.key !== "Escape") return;
  if (!_ovStack.length) return;
  if (document.querySelector("dialog[open]")) return;
  e.preventDefault();
  const top = _ovStack[_ovStack.length - 1];
  if (top.esc) {
    // رفتار اختصاصی (مثل برگشت از جزئیات شیت)؛ اگر واقعاً ببندد، از مسیر خودش
    // _ovClose/_ovRemove/_ovDetach عبور می‌کند و ورودی از استک درمی‌آید.
    top.esc();
    return;
  }
  _ovClose(false);
}
document.addEventListener("keydown", _ovEscKey, true);
