// text.js — ابزارهای مشترک متن: نرمال‌سازی جست‌وجو، debounce و هایلایت.
//
// هاب مرکزی «جست‌وجو و نرمال‌سازی» (نقشهٔ مرکزی‌سازی):
//   همهٔ جست‌وجوها (هدر، واژه‌نامه، کتابخانه، فروشگاه، پالت فرمان) از همین norm استفاده می‌کنند
//   و تأخیر ورودی‌ها با همین debounce اعمال می‌شود. هیچ کپی موازی از norm/esc/highlight
//   نباید ساخته شود. این ماژول خالص است: بدون DOM و بدون وابستگی به core.js.

import { escHtml } from "../engine/blocks/escape.js";

export { escHtml };

// نرمال‌سازی متن برای جست‌وجوی فارسی:
//   کوچک‌سازی، یکسان‌سازی «ي/ك» عربی به «ی/ک» فارسی، تبدیل ارقام فارسی و عربی به لاتین،
//   حذف اعراب و نیم‌فاصله و نشانه‌های جهت، فشردگی فاصله‌ها.
// هر دو سمت مقایسه (سوزن و متن) با همین تابع نرمال می‌شوند تا ارقام فارسی هم پیدا شوند.
export const norm = (s) =>
  (s || "")
    .toLowerCase()
    .replace(/ي/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/[۰-۹]/g, (d) => String("۰۱۲۳۴۵۶۷۸۹".indexOf(d)))
    .replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)))
    .replace(/[\u200c\u200e\u200f\u064b-\u0652\u0654\u0670]/g, "")
    .replace(/\s+/g, " ")
    .trim();

// debounce مشترک: اجرای تابع با تأخیر و لغو اجرای معلق قبلی.
// wrapped.cancel() برای پاک‌سازی هنگام جداشدن DOM.
export function debounce(fn, ms) {
  let t = 0;
  const wrapped = (...args) => {
    clearTimeout(t);
    t = setTimeout(() => fn(...args), ms);
  };
  wrapped.cancel = () => clearTimeout(t);
  return wrapped;
}

// الگوی هایلایتِ بخش‌به‌بخش: هر نویسهٔ سوزن به یک کلاس متحمل تبدیل می‌شود
// (ی/ي، ک/ك، ارقام فارسی، اعراب و فاصله بین حروف نادیده گرفته می‌شوند).
export const hlRe = (q) => {
  const ign = "[\\u200c\\u200e\\u200f\\u064b-\\u0652\\u0654\\u0670 ]*";
  const pat = [...String(q).trim()]
    .map((ch) => {
      if (ch === " ") return ign;
      if (ch === "ی") return "[یي]";
      if (ch === "ک") return "[کك]";
      if (/[0-9]/.test(ch)) return "[" + ch + "۰-۹]";
      if (/[.*+?^${}()|[\]\\]/.test(ch)) return "\\" + ch;
      return ch;
    })
    .join(ign);
  try {
    return new RegExp(pat, "gi");
  } catch (_) {
    return null;
  }
};

// هایلایت امن متن با سوزن: متن بین تطبیق‌ها escape می‌شود و خود تطابق داخل <mark> می‌رود.
// برخلاف جایگزینی regex روی رشتهٔ escape‌شده، هرگز داخل نهاد HTML (&amp;) تطبیق نمی‌سازد.
export function highlight(text, q) {
  const s = String(text == null ? "" : text);
  if (!q || String(q).trim().length < 2) return escHtml(s);
  const re = hlRe(q);
  if (!re) return escHtml(s);
  let out = "";
  let last = 0;
  let m;
  re.lastIndex = 0;
  while ((m = re.exec(s)) !== null) {
    if (m.index === re.lastIndex) re.lastIndex++;
    out += escHtml(s.slice(last, m.index)) + "<mark>" + escHtml(m[0]) + "</mark>";
    last = m.index + m[0].length;
  }
  out += escHtml(s.slice(last));
  return out;
}
