// ساخت دسته‌های مرور (Deck builder) — خالص، بدون DOM.
// دسته‌ها بعد از اعمال shouldIncludeCard ساخته می‌شوند؛ کارت‌های غیرفعال اصلاً در دسته‌ها نیستند،
// پس Deck.disabled همیشه false است و فقط برای سازگاری با شکل قبلی نگه داشته شده.

import { shouldIncludeCard, type CardSource } from "./card.js";

export interface Deck<C extends CardSource = CardSource> {
  id: string;
  title: string;
  cards: C[];
  disabled: boolean;
}

// نمای حداقلی یک درس: فقط فهرست جلسه‌ها برای عنوان دسته.
export interface CourseLike {
  sessions?: { id: string; title?: string; num?: number }[];
}

const FA_DIGITS = "۰۱۲۳۴۵۶۷۸۹";
const toFa = (n: number | string): string => String(n).replace(/\d/g, (d) => FA_DIGITS[+d] ?? d);

// عنوان نمایشی یک دسته. "s:<id>" جلسه است؛ اگر جلسه پیدا نشد، همان شناسه برمی‌گردد.
// unitEzafe: صورت اضافهٔ واحد درس («جلسهٔ»، «فصلِ»، …). پیش‌فرض، همان رفتار قدیمی موتور است؛
// صفحهٔ مرور فلش‌کارت، صورت اضافهٔ پک (unitWords) را می‌فرستد تا عنوان با بقیهٔ UI هم‌نام بماند.
export function deckTitle(
  deckId: string,
  course: CourseLike | null | undefined,
  unitEzafe: string = "جلسهٔ",
): string {
  if (deckId === "pack") return "کارت‌های درس";
  if (deckId === "user") return "کارت‌های من";
  if (deckId.indexOf("s:") === 0) {
    const sid = deckId.slice(2);
    const ss = (course?.sessions ?? []).find((x) => x.id === sid);
    return ss ? unitEzafe + " " + toFa(ss.num ?? "") + " — " + (ss.title ?? sid) : sid;
  }
  return deckId;
}

// کارت‌ها را بر اساس deck گروه می‌کند و فقط کارت‌های وارد‌شده را نگه می‌دارد.
// ترتیب: دسته‌ها به ترتیب اولین ظهور؛ دستهٔ "pack" همیشه آخر.
export function buildDecks<C extends CardSource>(
  cards: readonly C[],
  readSet: ReadonlySet<string>,
  course?: CourseLike | null,
): Deck<C>[] {
  const byId = new Map<string, Deck<C>>();
  for (const c of cards) {
    if (!shouldIncludeCard(c, readSet)) continue;
    let d = byId.get(c.deck);
    if (!d) {
      d = { id: c.deck, title: deckTitle(c.deck, course), cards: [], disabled: false };
      byId.set(c.deck, d);
    }
    d.cards.push(c);
  }
  const decks = [...byId.values()];
  return decks.sort((a, b) => (a.id === "pack" ? 1 : 0) - (b.id === "pack" ? 1 : 0));
}

// دسته‌بندی برای UI مرور فلش‌کارت: همهٔ کارت‌ها (حتی کارت جلسهٔ خوانده‌نشده و غیرفعال) گروه
// می‌شوند تا تب دسته دیده بماند؛ دسته‌ای که «همهٔ» کارت‌هایش غیرفعال است با disabled=true
// برچسب «غیرفعال» می‌گیرد. ترتیب: اولین ظهور؛ دستهٔ pack همیشه آخر.
// این همان منطقی است که قبلاً در flashcards.js کپی شده بود — اکنون تک‌نویسنده همین‌جاست.
export function buildDecksVerbose<C extends CardSource>(
  cards: readonly C[],
  course?: CourseLike | null,
  unitEzafe: string = "جلسهٔ",
): Deck<C>[] {
  const byId = new Map<string, Deck<C>>();
  for (const c of cards) {
    let d = byId.get(c.deck);
    if (!d) {
      d = { id: c.deck, title: deckTitle(c.deck, course, unitEzafe), cards: [], disabled: true };
      byId.set(c.deck, d);
    }
    d.cards.push(c);
    if (!c.disabled) d.disabled = false;
  }
  const decks = [...byId.values()];
  return decks.sort((a, b) => (a.id === "pack" ? 1 : 0) - (b.id === "pack" ? 1 : 0));
}

export const EMPTY_NO_CARDS = "این درس هنوز کارتی برای مرور ندارد.";
export const EMPTY_NO_READ =
  "هنوز هیچ جلسه‌ای را نخوانده‌اید؛ پس از خواندن یک جلسه، کارت‌هایش اینجا ظاهر می‌شوند.";

// پیام حالت خالی صفحهٔ مرور.
//  - "" اگر حداقل یک کارت وارد شده باشد.
//  - پیام «کارتی ندارد» اگر هیچ کارت فعالی در درس نباشد.
//  - پیام «جلسه‌ای نخوانده» اگر کارت فعال هست اما همه به دلیل خواندن نشدن بیرون‌اند.
export function emptyMessage(cards: readonly CardSource[], readSet: ReadonlySet<string>): string {
  const enabled = cards.filter((c) => !c.disabled);
  if (enabled.length === 0) return EMPTY_NO_CARDS;
  if (enabled.some((c) => shouldIncludeCard(c, readSet))) return "";
  return EMPTY_NO_READ;
}
