<script lang="ts">
  // درخت دوره‌ها در نوار کناری (Phase 7.3). هر دوره یک دکمهٔ سرتیتر است که واحدهایش را باز می‌کند.
  // فقط دسکتاپ/تبلت؛ گوشی از نوار تب استفاده می‌کند.
  import { nextIndex, type TreeCourse, type TreeUnit } from "./course-tree";


  let { courses }: { courses: readonly TreeCourse[] } = $props();

  // دوره‌ای که فعال است به‌طور پیش‌فرض باز است.
  let open = $state<Record<string, boolean>>({});
  const isOpen = (c: TreeCourse) => (c.id in open ? open[c.id] : c.active);

  let root: HTMLElement | undefined = $state();

  function toggle(c: TreeCourse) {
    if (!c.active) {
      location.hash = "#/p/" + encodeURIComponent(c.id);
      return;
    }
    open = { ...open, [c.id]: !isOpen(c) };
  }

  function openUnit(c: TreeUnit, packId: string) {
    location.hash = "#/p/" + encodeURIComponent(packId) + "/s/" + encodeURIComponent(c.sessionId);
  }

  // فلش‌ها بین همهٔ دکمه‌های درخت حرکت می‌کنند؛ Enter و Space را مرورگر خودش انجام می‌دهد.
  function onKey(e: KeyboardEvent) {
    if (!root) return;
    const items = Array.from(root.querySelectorAll<HTMLButtonElement>("button[data-tree]"));
    const i = items.indexOf(document.activeElement as HTMLButtonElement);
    if (i < 0) return;
    const next = nextIndex(e.key, i, items.length);
    if (next == null) return;
    e.preventDefault();
    items[next]?.focus();
  }
</script>

<div class="ct" bind:this={root}>
  {#each courses as course (course.id)}
    <div class="ct-course">
      <button
        class="ct-head"
        type="button"
        data-tree
        aria-expanded={course.active ? isOpen(course) : undefined}
        aria-controls={course.active ? "ct-" + course.id : undefined}
        aria-current={course.active ? "true" : undefined}
        onclick={() => toggle(course)}
        onkeydown={onKey}
      >
        <span class="ct-badge" aria-hidden="true">{course.title.charAt(0)}</span>
        <span class="ct-title">{course.title}</span>
        {#if course.active}
          <span class="ct-chev" class:on={isOpen(course)} aria-hidden="true">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="6 9 12 15 18 9" />
            </svg>
          </span>
        {/if}
      </button>
      {#if course.active}
        <div class="ct-panel" class:open={isOpen(course)} id={"ct-" + course.id}>
          <div class="ct-list">
            {#each course.units as unit (unit.id)}
              <button
                class="ct-unit"
                type="button"
                data-tree
                onclick={() => openUnit(unit, course.id)}
                onkeydown={onKey}
              >
                <span class="ct-dot" aria-hidden="true"></span>
                <span class="ct-unit-tx">{unit.label}</span>
              </button>
            {/each}
          </div>
        </div>
      {/if}
    </div>
  {/each}
</div>
