export interface TreeUnit {
  readonly id: string;
  readonly sessionId: string;
  readonly label: string;
}

export interface TreeCourse {
  readonly id: string;
  readonly title: string;
  readonly active: boolean;
  readonly unitWord: string;
  readonly units: readonly TreeUnit[];
}

/**
 * موقعیت بعدی فوکوس در فهرست. کلید ناشناخته یا فهرست خالی → null (یعنی کاری نکن).
 * ArrowDown/ArrowUp حلقه نمی‌زنند؛ در انتها و ابتدا می‌مانند.
 */
export function nextIndex(key: string, index: number, count: number): number | null {
  if (count <= 0) return null;
  switch (key) {
    case "ArrowDown":
      return Math.min(index + 1, count - 1);
    case "ArrowUp":
      return Math.max(index - 1, 0);
    case "Home":
      return 0;
    case "End":
      return count - 1;
    default:
      return null;
  }
}
