(function () {
  "use strict";
  const GAS = [
    { t: "انبساط آزادانه", v: 5.76, note: "V₂ = 2V₁ · یک مول" },
    { t: "اختلاط دو گاز", v: 11.5, note: "دو مول · x = 0.5" },
    { t: "گرمایش در حجم ثابت", v: 8.64, note: "T₂ = 2T₁ · یک مول" },
  ];
  const RXN = { t: "تجزیهٔ N₂O₄ → 2NO₂", v: 176, note: "۲۹۸ K · استاندارد" };

  function row(r, max, extra) {
    const pct = Math.max(3, (r.v / max) * 100);
    return (
      '<div style="display:grid;grid-template-columns:minmax(0,38%) 1fr 58px;align-items:center;gap:10px;margin:10px 0">' +
      '<div style="font-size:13px;line-height:1.5">' + r.t +
      '<div style="font-size:11px;opacity:.6">' + r.note + "</div></div>" +
      '<div style="height:16px;border-radius:99px;background:var(--surface-subtle);overflow:hidden">' +
      '<i data-fill style="display:block;height:100%;width:0;border-radius:99px;background:var(--accent);transition:width .9s cubic-bezier(.22,1,.36,1)" data-w="' + pct.toFixed(2) + '"></i></div>' +
      '<div dir="ltr" style="font-size:13px;font-weight:700;text-align:end">' + (r.v === 176 ? "≈ +176" : "+" + String(r.v)) + "</div>" +
      "</div>" +
      (extra || "")
    );
  }

  const W = {
    title: "چهار فرایند، چهار ΔS",
    desc: "واحد ΔS: J/K. در سه فرایند گازی آنتروپی بالا می‌رود، اما ظاهر سامانه تقریباً ثابت است.",
    mount(box) {
      box.innerHTML =
        '<div style="font-family:inherit">' +
        GAS.map((r) => row(r, 11.5)).join("") +
        '<div style="margin-top:14px;padding-top:12px;border-top:1px dashed currentColor;opacity:.95">' +
        row(RXN, 176, "") +
        '<div style="font-size:11px;opacity:.6;margin-top:-4px">نوار تجزیه با مقیاس جدا رسم شده است.</div>' +
        "</div></div>";
      requestAnimationFrame(() =>
        requestAnimationFrame(() =>
          box.querySelectorAll("[data-fill]").forEach((el) => {
            el.style.width = el.dataset.w + "%";
          }),
        ),
      );
    },
    unmount(box) {
      box.innerHTML = "";
    },
  };

  CourseRuntime.registerPackSource("entropy-metaphor", { widgets: { "entropy-bars": W } });
})();
