// برچسب‌های رابط کاربری (Phase 6.8 و 6.9).
// زنجیرهٔ جست‌وجو: pack.labels[key] → LABEL_REGISTRY[key] → خود کلید.
// واحد درسی (جلسه، فصل، …) جداگانه با unitName خوانده می‌شود، چون صورت مفرد، جمع و اضافه (ezafe) دارد.

export interface LabelSource {
  labels?: unknown;
}

/** پیش‌فرض‌های موتور. کلیدهای قدیمی meta (labTitle، problemsTitle) در normalize به این کلیدها نگاشت می‌شوند. */
export const LABEL_REGISTRY: Readonly<Record<string, string>> = Object.freeze({
  lab: "آزمایشگاه تعاملی",
  problems: "حل تمرین منتخب",
  review: "مرور",
  progress: "پیشرفت",
  glossary: "واژه‌نامه",
  refs: "مرجع روابط",
  plan: "برنامهٔ هفتگی",
  library: "کتابخانه",
  // کلیدهای نوار کناری که پیش‌فرض داشتند؛ متن همان چیزی است که قبلاً نمایش داده می‌شد.
  groupWork: "فضای کار",
  groupStudy: "مطالعه",
  home: "داشبورد",
  exam: "آزمون مروری",
  graph: "نقشهٔ مفاهیم",
  settings: "تنظیمات",
  // مقصدهای عمومی اپ (پک می‌تواند override کند)
  shop: "فروشگاه",
});

/** کلیدهای قدیمی meta → کلید برچسب. */
export const LEGACY_LABEL_KEYS: Readonly<Record<string, string>> = Object.freeze({
  labTitle: "lab",
  problemsTitle: "problems",
});

const DEV = (import.meta as { env?: { DEV?: boolean } }).env?.DEV === true;
const warned = new Set<string>();

function labelsOf(pack: LabelSource | null | undefined): Record<string, unknown> {
  const l = pack && pack.labels;
  return l && typeof l === "object" ? (l as Record<string, unknown>) : {};
}

/** برچسب یک کلید؛ همیشه رشته برمی‌گرداند. کلید ناشناخته در حالت توسعه یک بار هشدار می‌دهد. */
export function resolveLabel(pack: LabelSource | null | undefined, key: string): string {
  const fromPack = labelsOf(pack)[key];
  if (typeof fromPack === "string" && fromPack !== "") return fromPack;
  if (Object.prototype.hasOwnProperty.call(LABEL_REGISTRY, key))
    return LABEL_REGISTRY[key] as string;
  if (DEV && !warned.has(key)) {
    warned.add(key);
    console.warn(`[labels] برچسب ناشناخته: "${key}"`);
  }
  return key;
}

export interface UnitName {
  singular: string;
  plural: string;
  /** صورت اضافه: «جلسهٔ ۳»، «فصلِ ۳». */
  ezafe: string;
}

/** واحد پیش‌فرض موتور. */
export const DEFAULT_UNIT: Readonly<{ singular: string; plural: string }> = Object.freeze({
  singular: "جلسه",
  plural: "جلسات",
});

/** صورت اضافهٔ فارسی: مفرد به «ه» ختم شود «ه‌ٔ» (U+0654)، وگرنه کسرهٔ اضافه (U+0650). */
export function ezafeOf(word: string): string {
  if (!word) return word;
  return word.endsWith("ه") ? word + "ٔ" : word + "ِ";
}

/**
 * نام واحد پک از labels.unit. هر دو شکل پشتیبانی می‌شود:
 *   labels.unit = { singular: "فصل", plural: "فصل‌ها" }  یا  labels.unit = "فصل" (جمع = مفرد).
 * اگر پک چیزی ندهد، پیش‌فرض موتور (جلسه / جلسات) برمی‌گردد.
 */
export function unitName(pack: LabelSource | null | undefined): UnitName {
  const raw = labelsOf(pack).unit;
  let singular: string = DEFAULT_UNIT.singular;
  let plural: string = DEFAULT_UNIT.plural;
  if (typeof raw === "string" && raw.trim()) {
    singular = raw.trim();
    plural = raw.trim();
  } else if (raw && typeof raw === "object") {
    const o = raw as { singular?: unknown; plural?: unknown };
    if (typeof o.singular === "string" && o.singular.trim()) singular = o.singular.trim();
    if (typeof o.plural === "string" && o.plural.trim()) plural = o.plural.trim();
    else if (typeof o.singular === "string" && o.singular.trim()) plural = singular;
  }
  return { singular, plural, ezafe: ezafeOf(singular) };
}

/** نسخهٔ قدیمی: برای کدهایی که فقط مفرد لازم دارند. */
export function unitWord(pack: LabelSource | null | undefined): string {
  return unitName(pack).singular;
}

/** تست و توسعه: بازنشانی هشدارهای یکباره. */
export function resetLabelWarnings(): void {
  warned.clear();
}
