// fa-format.js — هاب مرکزی «فرمت فارسی و ارقام».
//
// هر متن عددی/تاریخی رابط باید از همین ماژول فرمت شود؛ نوشتن مستقیم ارقام لاتین در UI
// و تعریف toFa/فرمت‌کنندهٔ موازی مجاز نیست. این ماژول خالص است: بدون DOM و بدون core.js.
//
// محتوا:
//   FA / toFa        — ارقام لاتین → فارسی (کانonical؛ core.js هم re-export می‌کند)
//   fmtCompact(n)    — عدد فشردهٔ آمار («۱۲K» با ارقام فارسی)
//   relTimeFa(ts)    — زمان نسبی گذشته («۳ دقیقه پیش»، «دیروز»، …)

export const FA = "۰۱۲۳۴۵۶۷۸۹";

// ارقام لاتین → ارقام فارسی. ورودی هر نوعی می‌تواند باشد (عدد یا رشته).
export const toFa = (x) => String(x).replace(/\d/g, (d) => FA[d] ?? d);

// عدد فشرده برای کاشی‌های آمار: هزار به‌ بالا به شکل «۱۲K» و همیشه با ارقام فارسی.
export function fmtCompact(n) {
  n = Number(n) || 0;
  if (n >= 1000) return toFa((Math.round(n / 100) / 10).toFixed(0)) + "K";
  return toFa(n);
}

// زمان نسبی گذشته برای اعلان‌ها و رویدادها؛ همان طبقه‌بندی زنگ اعلان شل.
export function relTimeFa(ts) {
  if (!Number.isFinite(ts) || ts <= 0) return "—";
  const diff = Date.now() - ts;
  if (diff < 0) return "در آینده";
  const s = Math.floor(diff / 1000);
  if (s < 60) return toFa(s) + " ثانیه پیش";
  const m = Math.floor(s / 60);
  if (m < 60) return toFa(m) + " دقیقه پیش";
  const h = Math.floor(m / 60);
  if (h < 24) return toFa(h) + " ساعت پیش";
  const d = Math.floor(h / 24);
  if (d === 1) return "دیروز";
  if (d < 7) return toFa(d) + " روز پیش";
  if (d < 30) return toFa(Math.floor(d / 7)) + " هفته پیش";
  return toFa(Math.floor(d / 30)) + " ماه پیش";
}
