<script lang="ts">
  // پنجرهٔ شروع (Phase 7.4): خوش‌آمد و سه پرسش اختیاری. mode="first" با خوش‌آمد شروع می‌شود؛
  // mode="edit" از تنظیمات باز می‌شود و مستقیم به پرسش‌ها می‌رود. استایل در src/styles/lector-ui.css.
  import { onMount, tick } from "svelte";
  import { iconSvg } from "../mount-helpers";
  import {
    GOAL_LABEL,
    GOAL_OPTIONS,
    WHO_LABEL,
    WHO_OPTIONS,
    type FirstRunAnswers,
    type Goal,
    type Who,
  } from "../../first-run/model";

  type Pack = { id: string; title: string };
  let {
    mode,
    initial,
    packs,
    onfinish,
    oncancel,
  }: {
    mode: "first" | "edit";
    initial: FirstRunAnswers;
    packs: Pack[];
    onfinish: (a: FirstRunAnswers) => void;
    oncancel: () => void;
  } = $props();

  const WHO_HINT: Record<Who, string> = {
    self: "بدون استاد، برای یادگیری خودم",
    student: "برای درس مدرسه یا دانشگاه",
    other: "هر کاربرد دیگری",
  };
  const GOAL_HINT: Record<Goal, string> = {
    learn: "از اول می‌خوانم و مفهوم‌ها را می‌سازم",
    review: "چیزهایی را که خوانده‌ام تثبیت کنم",
    exam: "امتحان نزدیک است",
  };

  // مرحله‌ها: خوش‌آمد (فقط اولین بار)، سپس سه پرسش.
  const steps = $derived(mode === "first" ? ["welcome", "who", "course", "goal"] : ["who", "course", "goal"]);
  let i = $state(0);
  let answers = $state<FirstRunAnswers>({ ...initial });
  const step = $derived(steps[i]);
  const isLast = $derived(i === steps.length - 1);
  // پیشرفت فقط روی سه پرسش: خوش‌آمد نوار پیشرفت ندارد.
  const questionCount = 3;
  const questionIndex = $derived(step === "welcome" ? -1 : steps.indexOf(step) - (mode === "first" ? 1 : 0));
  const showBack = $derived(i > 0 && !(mode === "first" && i === 1));

  let dlg: HTMLDialogElement | undefined = $state();
  let headingEl: HTMLElement | undefined = $state();

  onMount(() => {
    dlg?.showModal();
    dlg?.querySelector<HTMLButtonElement>("[data-primary]")?.focus();
  });

  // با تغییر مرحله فوکوس به عنوان می‌رود تا کیبورد و خوانندهٔ صفحه جا را گم نکنند.
  $effect(() => {
    void step;
    tick().then(() => headingEl?.focus({ preventScroll: true }));
  });

  function next() {
    if (isLast) onfinish({ ...answers });
    else i += 1;
  }
  function back() {
    if (i > 0) i -= 1;
  }
  function skip() {
    // پاسخ این پرسش را خالی می‌گذارد و جلو می‌رود.
    if (step === "who") answers = { ...answers, who: null };
    if (step === "course") answers = { ...answers, course: null };
    if (step === "goal") answers = { ...answers, goal: null };
    next();
  }
  function pickWho(v: Who) {
    answers = { ...answers, who: v };
  }
  function pickCourse(id: string) {
    answers = { ...answers, course: id };
  }
  function pickGoal(v: Goal) {
    answers = { ...answers, goal: v };
  }
  // Esc در خوش‌آمد بسته نمی‌شود، چون گذشتن از آن بی‌صدا پاسخ‌ها را خالی می‌گذارد.
  function onCancel(e: Event) {
    e.preventDefault();
    if (mode === "edit") oncancel();
  }
</script>

<dialog bind:this={dlg} class="fr" aria-labelledby="fr-title" data-step={step} oncancel={onCancel}>
  <div class="fr-shell">
    <header class="fr-top">
      <span class="fr-brand">Lector</span>
      {#if questionIndex >= 0}
        <div class="fr-prog" aria-hidden="true">
          {#each Array(questionCount) as _, k (k)}
            <span class:on={k <= questionIndex}></span>
          {/each}
        </div>
      {/if}
    </header>

    {#key step}
      <div class="fr-body">
        {#if step === "welcome"}
          <div class="fr-hero">
            <span class="fr-mark" aria-hidden="true">{@html iconSvg("book")}</span>
            <h2 id="fr-title" bind:this={headingEl} tabindex="-1">به Lector خوش آمدی</h2>
            <p class="fr-lead">
              درسنامه‌های تعاملی را برای مطالعهٔ شخصی تو باز می‌کنیم. سه پرسش کوتاه، و همه‌اش اختیاری.
            </p>
            <ul class="fr-points">
              <li>درسنامهٔ تعاملی با مثال و تمرین</li>
              <li>مرور با زمان‌بندی؛ هر مفهوم سر وقتش</li>
              <li>صفحهٔ شروعی که با هدفت جور است</li>
            </ul>
          </div>
        {:else if step === "who"}
          <h2 id="fr-title" bind:this={headingEl} tabindex="-1">تو کدام گروهی؟</h2>
          <p class="fr-lead">برای چیدمان صفحهٔ شروع. هر وقت خواستی می‌توانی تغییرش بدهی.</p>
          <div class="fr-cards" role="group" aria-label="گروه">
            {#each WHO_OPTIONS as w (w)}
              <button type="button" class="fr-card" aria-pressed={answers.who === w} onclick={() => pickWho(w)}>
                <span class="fr-card-body">
                  <span class="fr-card-t">{WHO_LABEL[w]}</span>
                  <span class="fr-card-h">{WHO_HINT[w]}</span>
                </span>
                <span class="fr-radio" aria-hidden="true"></span>
              </button>
            {/each}
          </div>
        {:else if step === "course"}
          <h2 id="fr-title" bind:this={headingEl} tabindex="-1">کدام درس را می‌خوانی؟</h2>
          <p class="fr-lead">درسی را که الان بیشتر با آن کار می‌کنی انتخاب کن.</p>
          {#if packs.length}
            <div class="fr-cards" role="group" aria-label="درس">
              {#each packs as p (p.id)}
                <button type="button" class="fr-card" aria-pressed={answers.course === p.id} onclick={() => pickCourse(p.id)}>
                  <span class="fr-card-body">
                    <span class="fr-card-t">{p.title}</span>
                  </span>
                  <span class="fr-radio" aria-hidden="true"></span>
                </button>
              {/each}
            </div>
          {:else}
            <p class="fr-lead">هنوز درسی نصب نشده است.</p>
          {/if}
        {:else if step === "goal"}
          <h2 id="fr-title" bind:this={headingEl} tabindex="-1">هدفت چیست؟</h2>
          <p class="fr-lead">صفحهٔ شروع و کارهای نمایان بر اساس همین انتخاب تنظیم می‌شوند.</p>
          <div class="fr-cards" role="group" aria-label="هدف">
            {#each GOAL_OPTIONS as g (g)}
              <button type="button" class="fr-card" aria-pressed={answers.goal === g} onclick={() => pickGoal(g)}>
                <span class="fr-card-body">
                  <span class="fr-card-t">{GOAL_LABEL[g]}</span>
                  <span class="fr-card-h">{GOAL_HINT[g]}</span>
                </span>
                <span class="fr-radio" aria-hidden="true"></span>
              </button>
            {/each}
          </div>
        {/if}
      </div>
    {/key}

    <footer class="fr-foot">
      {#if step === "welcome"}
        <button type="button" class="fr-btn primary wide" data-primary onclick={next}>شروع</button>
      {:else}
        <div class="fr-foot-row">
          {#if showBack}
            <button type="button" class="fr-btn ghost" onclick={back}>بازگشت</button>
          {:else}
            <span></span>
          {/if}
          <button type="button" class="fr-btn primary" data-primary onclick={next}>
            {isLast ? "ذخیره" : "ادامه"}
          </button>
        </div>
        <button type="button" class="fr-skip" onclick={skip}>رد کردن</button>
      {/if}
    </footer>
  </div>
</dialog>
